typedef float vm_num_t;

class stringx;
stringx operator+(const char*, const stringx&);

class vm_thread;

class vm_stack {
public:
  int salloc;
  char* buffer;
  char* SP;
  vm_thread* my_thread;

  char* get_SP() const { return SP; }
  void pop(int n) { SP -= n; }
  bool push(const char* src, int n);
};

class vm_executable {
  char pad0[0x34];
  int parms_stacksize;
  char pad1[4];
  unsigned short* buffer;
public:
  const stringx& get_fullname() const;
  int get_parms_stacksize() const { return parms_stacksize; }
  const unsigned short* get_start() const { return buffer; }
};

class script_object {
public:
  class instance {
  public:
    vm_thread* add_thread(const vm_executable* ex);
  };
};

class vm_thread {
protected:
  union argument_t {
    vm_num_t val;
    short word;
    char* sdr;
    void* lfr;
    vm_executable* sfr;
    unsigned binary;
  };

  enum flags_t {
    SUSPENDED = 0x0001,
    SUSPENDABLE = 0x0002,
  };

  script_object::instance* inst;
  const vm_executable* ex;
  unsigned int flags;
  vm_stack dstack;
  const unsigned short* PC;
  char pad0[0x18];
  float camera_priority;

public:
  void set_suspendable(bool v);
  bool is_suspendable() const { return flags & SUSPENDABLE; }
  void set_camera_priority(float pr);
  float get_camera_priority() { return camera_priority; }
  void slf_error(const stringx& err);

protected:
  void spawn_sub_thread(const argument_t& arg);
};

void vm_thread::spawn_sub_thread( const argument_t& arg )
{
  vm_thread* newvmt = inst->add_thread(arg.sfr);

  newvmt->set_suspendable( is_suspendable() );

  newvmt->set_camera_priority( get_camera_priority() );

  int psize = arg.sfr->get_parms_stacksize();
  if ( psize )
  {
    if ( !newvmt->dstack.push(dstack.get_SP()-psize,psize) )
      slf_error( "stack overflow spawning " + arg.sfr->get_fullname() );
  }
  newvmt->PC = arg.sfr->get_start();
  dstack.pop( psize );
}
